DROP POLICY hotel_reviews_customer ON public.hotel_booking_reviews;
DROP POLICY hotel_workflow_customer_read ON public.hotel_workflow_settings;
CREATE FUNCTION hotel_private.customer_hotel_review(p_booking_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.bookings; result jsonb; BEGIN SELECT * INTO b FROM public.bookings WHERE id=p_booking_id; IF b.id IS NULL OR b.customer_id IS DISTINCT FROM public.current_customer_id(b.tenant_id) THEN RAISE EXCEPTION 'Not your booking'; END IF;
SELECT jsonb_build_object('checklist',COALESCE(r.checklist,'{}'),'customer_message',r.customer_message,'collection_time',r.collection_time,'approved_at',r.approved_at,'payment_verified',r.verified_payment_id IS NOT NULL,'payment_percent_override',r.payment_percent_override,'estimate',CASE WHEN e.id IS NULL THEN NULL ELSE jsonb_build_object('id',e.id,'estimate_number',e.estimate_number,'total',e.total,'extras',e.extras) END,'public_settings',jsonb_build_object('approval_checklist',w.approval_checklist,'payment_cutoff_days',w.payment_cutoff_days,'advance_deposit_pct',w.advance_deposit_pct)) INTO result FROM public.hotel_workflow_settings w LEFT JOIN public.hotel_booking_reviews r ON r.booking_id=b.id LEFT JOIN public.estimates e ON e.id=r.estimate_id WHERE w.tenant_id=b.tenant_id; RETURN result; END $$;
REVOKE ALL ON FUNCTION hotel_private.customer_hotel_review(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION hotel_private.customer_hotel_review(uuid) TO authenticated;
CREATE FUNCTION public.customer_hotel_review(p_booking_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT hotel_private.customer_hotel_review(p_booking_id) $$;
REVOKE ALL ON FUNCTION public.customer_hotel_review(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.customer_hotel_review(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.hotel_invalidate_approval() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid; eid uuid; BEGIN IF TG_TABLE_NAME='bookings' THEN bid:=NEW.id; ELSE bid:=COALESCE(NEW.booking_id,OLD.booking_id); END IF; SELECT estimate_id INTO eid FROM public.hotel_booking_reviews WHERE booking_id=bid AND verified_payment_id IS NULL; IF eid IS NOT NULL THEN UPDATE public.estimates SET status='expired',hold_until=NULL,hold_expires_at=NULL WHERE id=eid AND converted_invoice_id IS NULL; END IF; UPDATE public.hotel_booking_reviews SET approved_at=NULL,approved_by=NULL,estimate_id=NULL WHERE booking_id=bid AND verified_payment_id IS NULL; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $$;
DO $m$ DECLARE d text; BEGIN SELECT pg_get_functiondef('hotel_private.hotel_review_action(uuid,text,jsonb)'::regprocedure) INTO d; d:=replace(d,'IF p_action=''save'' OR p_action=''needs_info'' THEN','IF p_action=''save'' OR p_action=''needs_info'' THEN
 IF r.estimate_id IS NOT NULL THEN UPDATE public.estimates SET status=''expired'',hold_until=NULL,hold_expires_at=NULL WHERE id=r.estimate_id AND converted_invoice_id IS NULL; END IF;'); d:=replace(d,'collection_time=NULLIF(p_data->>''collection_time'','''')::time,approved_at=NULL','collection_time=NULLIF(p_data->>''collection_time'','''')::time,estimate_id=NULL,approved_at=NULL'); EXECUTE d; END $m$;